import * as fs from 'fs';
import * as path from 'path';

import { getChangeDir } from '../lib/change';
import { kebabCasePattern } from '../schemas';

const MAX_NAME_LENGTH = 128;

/**
 * Create a new change directory with its `workflow.json` metadata file.
 * Replaces `openspec new change` from the bundled openspec CLI.
 *
 * - The ONE AND ONLY creator of `openspec/changes/<name>/workflow.json`;
 *   `getWorkflowType` / `writeEvalJson` throw when that file is missing, so a
 *   directory without it can only be repaired by the user (writing the file to
 *   match `workflowFileSchema`) or by re-creating the change.
 * - Validates `name` is kebab-case (`^[a-z0-9][a-z0-9-]*$`, max 128 chars).
 * - Rejects the change if `openspec/changes/<name>/` already exists — an
 *   existing directory is never repaired or back-filled.
 * - Creates the directory and writes `workflow.json` with `workflow_type` and
 *   `created` only. `workflow_type` MUST be a member of `workflowTypeSchema`
 *   (`requirement` / `bug-fix` / `refactor` / `test-only`), enforced by the
 *   MCP input schema.
 * - MUST NOT write an `eval` key (not even `"eval": []`) — an explicit empty
 *   array would shadow the legacy `eval.json` read fallback.
 * - MUST NOT create `eval.json`; that file is only ever read (legacy fallback)
 *   and deleted by `writeEvalJson` after migration.
 * - Does NOT write `.openspec.yaml`.
 *
 * Returns `{ name, path }` where `path` is the created change directory.
 */
export function runChangeCreate(
  name: string,
  projectRoot: string,
  workflowType: string,
): {
  name: string;
  path: string;
} {
  if (!kebabCasePattern.test(name)) {
    throw new Error(
      `name 必须为 kebab-case（小写字母/数字，可用 \`-\` 连接，最长 128 字符），收到: ${JSON.stringify(name)}`,
    );
  }
  if (name.length > MAX_NAME_LENGTH) {
    throw new Error(`name 长度超过 ${MAX_NAME_LENGTH} 字符限制（当前 ${name.length} 字符）`);
  }

  const changeDir = getChangeDir(name, projectRoot);
  if (fs.existsSync(changeDir)) {
    throw new Error(`change "${name}" 已存在: ${changeDir}`);
  }

  fs.mkdirSync(changeDir, { recursive: true });
  const created = new Date().toISOString().slice(0, 10);
  // Contract: only `workflow_type` + `created` — no `eval` key, no `eval.json`.
  const workflow = { workflow_type: workflowType, created };
  fs.writeFileSync(path.join(changeDir, 'workflow.json'), `${JSON.stringify(workflow)}\n`, 'utf-8');

  return { name, path: changeDir };
}

