    writeEvalJson(dir, [makeEntry()]);

    const doc = readWorkflow(dir);
    expect(Object.prototype.hasOwnProperty.call(doc, 'created')).toBe(false);
    expect(doc.workflow_type).toBe('requirement');
  });
});

